{"command": "python3 <<'PY'
import subprocess, os, pty, time

def test(n, args=[]):
    master, slave = pty.openpty()
    large = b'<root>'+b'<a>hi</a>'*n+b'</root>'
    p = subprocess.Popen(['./executable']+args, stdin=subprocess.PIPE, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    p.stdin.write(large)
    p.stdin.close()
    os.set_blocking(master, False)
    try:
        p.wait(timeout=3)
        timed=False
    except subprocess.TimeoutExpired:
        print(f"n={n} args={args} TIMEOUT")
        p.kill()
        p.wait()
        # drain
        time.sleep(0.2)
        out=b""
        try:
            while True:
                try:
                    d=os.read(master, 16384)
                    if not d: break
                    out+=d
                except BlockingIOError:
                    break
        except OSError:
            pass
        print(f"  drained {len(out)} bytes, lines {out.count(b'\\n')}")
        os.close(master)
        return
    time.sleep(0.2)
    out=b""
    try:
        while True:
            try:
                d=os.read(master, 16384)
                if not d: break
                out+=d
            except BlockingIOError:
                break
    except OSError:
        pass
    os.close(master)
    print(f"n={n} args={args} OK out_len={len(out)} lines={out.count(b'\\n')}")

for n in [300,400,450,500]:
    test(n, [])
for n in [500,1000]:
    test(n, ['--no-color'])
for n in [500]:
    test(n, ['--color'])
PY"}

