{"command": "python3 <<'PY'
import subprocess, os, pty, time, threading, select
def test_concurrent(n, args=[]):
    master, slave = pty.openpty()
    large = b'<root>'+b'<a>hi</a>'*n+b'</root>'
    p = subprocess.Popen(['./executable']+args, stdin=subprocess.PIPE, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    p.stdin.write(large)
    p.stdin.close()
    out_chunks=[]
    def reader():
        import os, select
        while True:
            r,_,_ = select.select([[master]], [], [], 5)
            # select expects? fix
            break
    # simpler: use blocking read in thread with timeout via os.set_blocking False + poll
    def reader2():
        import os, time
        os.set_blocking(master, False)
        start=time.time()
        while time.time()-start<6:
            try:
                d=os.read(master, 16384)
                if d:
                    out_chunks.append(d)
                    start=time.time()
                else:
                    time.sleep(0.1)
                    # check if process exited and no data?
                    if p.poll() is not None:
                        # try drain once more
                        try:
                            d2=os.read(master, 16384)
                            if d2:
                                out_chunks.append(d2)
                                continue
                        except: pass
                        break
            except BlockingIOError:
                time.sleep(0.05)
                if p.poll() is not None:
                    # give a bit
                    continue
            except OSError:
                break
    t=threading.Thread(target=reader2)
    t.start()
    try:
        p.wait(timeout=6)
        print(f"n={n} args={args} exited rc={p.returncode}")
    except subprocess.TimeoutExpired:
        print(f"n={n} args={args} TIMEOUT concurrent")
        p.kill()
        p.wait()
    t.join(timeout=2)
    try: os.close(master)
    except: pass
    total=b"".join(out_chunks)
    print(f"  total len {len(total)}")

for n in [500, 450]:
    test_concurrent(n, [])
PY"}

