package main
import (
  "encoding/xml"
  "fmt"
  "os"
)
func main(){
  data,_:=os.ReadFile(os.Args[1])
  dec:=xml.NewDecoder(os.Stdin)
  _=data
  for {
    tok,err:=dec.Token()
    if err!=nil{fmt.Printf("ERR %v\n",err); break}
    fmt.Printf("%T %q\n",tok,tok)
  }
}
