package main
import (
  "encoding/xml"
  "fmt"
  "bytes"
)
func main(){
  tests := []string{
    `<a>hi   <b>x</b></a>`,
    `<a>hi   `+"\n"+`   </a>`,
    `<a>hi   `+"\n"+`</a>`,
  }
  for _, s := range tests {
    fmt.Printf("=== %q\n", s)
    dec:=xml.NewDecoder(bytes.NewBufferString(s))
    for {
      tok,err:=dec.Token()
      if err!=nil{fmt.Printf("ERR %v\n",err); break}
      fmt.Printf("%T %q\n",tok,tok)
      if _,ok:=tok.(xml.EndElement); ok { break }
    }
  }
}
