				} else {
					setBool(opts, d.long, true)
				}
			case "string":
				var s string
				if hasVal {
					s = val
				} else {
					if i+1 >= len(args) {
						return nil, fmt.Sprintf("Error: flag needs an argument: --%s\n", name)
