type flagDef struct {
	shorthand string
	long      string
	typ       string // "bool", "string", "int"
}

var flagDefs = []flagDef{
	{"a", "attr", "string"},
	{"c", "color", "bool"},
	{"", "compact", "bool"},
	{"d", "depth", "int"},
	{"e", "extract", "string"},
	{"h", "help", "bool"},
	{"m", "html", "bool"},
	{"i", "in-place", "bool"},
	{"", "indent", "int"},
	{"j", "json", "bool"},
	{"", "no-color", "bool"},
	{"n", "node", "bool"},
	{"q", "query", "string"},
	{"", "tab", "bool"},
	{"v", "version", "bool"},
	{"x", "xpath", "string"},
}

func findByLong(name string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].long == name {
			return &flagDefs[i]
		}
	}
	return nil
}

func findByShort(ch byte) *flagDef {
	s := string(ch)
	for i := range flagDefs {
		if flagDefs[i].shorthand == s {
			return &flagDefs[i]
		}
	}
	return nil
}

func displayName(d *flagDef) string {
	if d.shorthand != "" {
		return fmt.Sprintf("\"-%s, --%s\"", d.shorthand, d.long)
	}
	return fmt.Sprintf("\"--%s\"", d.long)
}

func parseBool(s string) (bool, error) {
	return strconv.ParseBool(s)
}

func parseFlags(args []string, opts *options) ([]string, string) {
	var positional []string
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			// terminator
			positional = append(positional, args[i+1:]...)
			break
		}
		if len(arg) >= 3 && strings.HasPrefix(arg, "--") {
			// long flag
			eq := strings.Index(arg, "=")
			var name, val string
			var hasVal bool
			if eq >= 0 {
				name = arg[2:eq]
				val = arg[eq+1:]
				hasVal = true
			} else {
				name = arg[2:]
				hasVal = false
			}
			d := findByLong(name)
			if d == nil {
				return nil, fmt.Sprintf("Error: unknown flag: --%s\n", name)
			}
			switch d.typ {
			case "bool":
				if hasVal {
					b, err := parseBool(val)
					if err != nil {
						return nil, fmt.Sprintf("Error: invalid argument %q for %s flag: strconv.ParseBool: parsing %q: invalid syntax\n", val, displayName(d), val)
					}
					setBool(opts, d.long, b)
				} else {
					setBool(opts, d.long, true)
				}
			case "string":
				var s string
				if hasVal {
					s = val
				} else {
					if i+1 >= len(args) {
						return nil, fmt.Sprintf("Error: flag needs an argument: --%s\n", name)
					}
					i++
					s = args[i]
				}
				setString(opts, d.long, s)
			case "int":
				var s string
				if hasVal {
					s = val
				} else {
					if i+1 >= len(args) {
						return nil, fmt.Sprintf("Error: flag needs an argument: --%s\n", name)
					}
					i++
					s = args[i]
				}
				// for indent/depth, show displayName accordingly
				// indent has no shorthand, depth has shorthand
				n, err := strconv.ParseInt(s, 10, 64)
				if err != nil {
					// need to match original: for indent, display is "--indent", for depth, "-d, --depth"
					return nil, fmt.Sprintf("Error: invalid argument %q for %s flag: strconv.ParseInt: parsing %q: invalid syntax\n", s, displayName(d), s)
				}
				setInt(opts, d.long, int(n))
			}
			i++
			continue
		}
		if len(arg) >= 2 && strings.HasPrefix(arg, "-") && arg != "-" {
			// shorthand cluster
			cluster := arg[1:]
			j := 0
			consumedAsValue := false
			for j < len(cluster) {
				ch := cluster[j]
				d := findByShort(ch)
				if d == nil {
					// unknown shorthand, show remainder from j?
					// original shows "in -<remainder>" where remainder is cluster[j:] with dash?
					// For "-color" with unknown 'o' at j=1, remainder is "olor", shows "-olor"
					// For "-tab" with unknown 't' at j=0, remainder is "tab", shows "-tab"
					// For "-in-place" with unknown '-' at j=2, remainder is "-place", shows "--place" (dash + remainder)?
					// Actually cluster is "in-place", j=2 char '-', remainder "-place", shows "--place" (dash prefix + remainder)
					// So display is "-" + cluster[j:] ? For j=1 in "color", cluster[j:]="olor", display "-olor" matches.
					// For j=2 in "in-place", cluster[j:]="-place", display "-"+"-place"="--place" matches.
					return nil, fmt.Sprintf("Error: unknown shorthand flag: '%c' in -%s\n", ch, cluster[j:])
				}
				switch d.typ {
				case "bool":
					// check if remainder starts with '=' and has value?
					rest := cluster[j+1:]
					if len(rest) > 0 && rest[0] == '=' {
						after := rest[1:]
						if len(after) > 0 {
							// value present, parse as bool
							b, err := parseBool(after)
							if err != nil {
								return nil, fmt.Sprintf("Error: invalid argument %q for %s flag: strconv.ParseBool: parsing %q: invalid syntax\n", after, displayName(d), after)
							}
							setBool(opts, d.long, b)
							// consumed rest, break cluster
							j = len(cluster)
							consumedAsValue = true
							break
						} else {
							// remainder is exactly "=", treat '=' as unknown?
							return nil, fmt.Sprintf("Error: unknown shorthand flag: '=' in -%s\n", cluster[j+1:])
						}
					} else {
						setBool(opts, d.long, true)
						j++
					}
				case "string", "int":
					rest := cluster[j+1:]
					var s string
					if len(rest) > 0 {
						// attached value
						if rest[0] == '=' {
							if len(rest) == 1 {
								// exactly "=", value is "="
								s = "="
							} else {
								s = rest[1:]
							}
						} else {
							s = rest
						}
						// set and break cluster
						if d.typ == "string" {
							setString(opts, d.long, s)
						} else {
							n, err := strconv.ParseInt(s, 10, 64)
							if err != nil {
								return nil, fmt.Sprintf("Error: invalid argument %q for %s flag: strconv.ParseInt: parsing %q: invalid syntax\n", s, displayName(d), s)
							}
							setInt(opts, d.long, int(n))
						}
						j = len(cluster)
						consumedAsValue = true
						break
					} else {
						// need next arg
						if i+1 >= len(args) {
							return nil, fmt.Sprintf("Error: flag needs an argument: '%c' in -%s\n", ch, cluster)
						}
						i++
						s = args[i]
						if d.typ == "string" {
							setString(opts, d.long, s)
						} else {
							n, err := strconv.ParseInt(s, 10, 64)
							if err != nil {
								return nil, fmt.Sprintf("Error: invalid argument %q for %s flag: strconv.ParseInt: parsing %q: invalid syntax\n", s, displayName(d), s)
							}
							setInt(opts, d.long, int(n))
						}
						j = len(cluster)
						consumedAsValue = true
						break
					}
				}
			}
			_ = consumedAsValue
			i++
			continue
		}
		// positional
		positional = append(positional, arg)
		i++
	}
	return positional, ""
}

