				if prevIsComment || prevIsDirective || prevIsProc {
					buf.WriteString("\n")
				}
			}
			if useColor {
				buf.WriteString("\x1b[94m<!--\x1b[0m")
				buf.WriteString("\x1b[94m" + c + "\x1b[0m")
				buf.WriteString("\x1b[94m-->\x1b[0m")
			} else {
				buf.WriteString("<!--" + c + "-->")
			}
			first = false
			prevIsComment = true
			prevIsDirective = false
			prevIsProc = false
			prevIsEnd = false
		case xml.Directive:
			d := string(t)
			if len(stack) > 0 && stack[len(stack)-1].needClose {
				writeCloseBracket()
				stack[len(stack)-1].needClose = false
				stack[len(stack)-1].hasElem = true
			} else if len(stack) > 0 {
				stack[len(stack)-1].hasElem = true
			}
			formatted := formatDirective(d)
			if useColor {
				lower := strings.ToLower(strings.TrimSpace(formatted))
				isDoctype := strings.HasPrefix(lower, "doctype")
				if isDoctype {
					idx := strings.Index(formatted, " ")
					var rest string
					if idx >= 0 {
						rest = formatted[idx+1:]
						buf.WriteString("\x1b[33m<!doctype \x1b[0m")
						buf.WriteString(rest)
						buf.WriteString("\x1b[33m>\x1b[0m")
					} else {
						buf.WriteString("\x1b[33m<!" + formatted + "\x1b[0m")
						buf.WriteString("\x1b[33m>\x1b[0m")
					}
				} else {
					buf.WriteString("\x1b[33m<!\x1b[0m")
					buf.WriteString(formatted)
					buf.WriteString("\x1b[33m>\x1b[0m")
				}
			} else {
				buf.WriteString("<!" + formatted + ">")
			}
			first = false
			prevIsDirective = true
			prevIsComment = false
			prevIsProc = false
			prevIsEnd = false
		case xml.ProcInst:
			target := t.Target
			inst := string(t.Inst)
			if len(stack) > 0 && stack[len(stack)-1].needClose {
				// do not close, keep needClose
			} else if len(stack) == 0 && !first && indentStr != "" {
				// top-level PI after previous? Start handling will add newline for next element, but PI itself inline? For PI after element at top, inline (no newline). Do nothing.
			}
			piStr := formatProcInst(target, inst, useColor)
			buf.WriteString(piStr)
			first = false
			prevIsProc = true
			prevIsComment = false
			prevIsDirective = false
			prevIsEnd = false
		}
	}
	s := buf.String()
	if !strings.HasSuffix(s, "\n") {
		s += "\n"
	}
	if (prevIsComment || prevIsDirective || prevIsProc) && len(stack) == 0 {
		s += "\n"
	}
	return s, ""
}
