		return string(b)
	case []interface{}:
		if len(x) == 0 {
			return "{\n\n" + indent + "}"
		}
		// Actually for empty array, should be "[\n\n...]" not "{...}" – fix below
		return ""
	default:
		return ""
	}
	_ = indent
