		if len(x) == 0 {
			return "\x1b[33m[\x1b[0m\n\n" + indent + "\x1b[33m]\x1b[0m"
		}
		parts := make([]string, len(x))
		for i, e := range x {
			parts[i] = nextIndent + marshalPrettyColor(e, level+1)
		}
		return "\x1b[33m[\x1b[0m\n" + strings.Join(parts, ",\n") + "\n" + indent + "\x1b[33m]\x1b[0m"
