		for k := range x {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		parts := make([]string, len(keys))
		for i, k := range keys {
			kb, _ := json.Marshal(k)
			parts[i] = nextIndent + "\x1b[94m" + string(kb) + "\x1b[0m" + ": " + marshalPrettyColor(x[k], level+1)
		}
		return "\x1b[33m{\x1b[0m\n" + strings.Join(parts, ",\n") + "\n" + indent + "\x1b[33m}\x1b[0m"
	default:
		b, _ := json.Marshal(v)
		return "\x1b[32m" + string(b) + "\x1b[0m"
	}
