		if len(x) == 0 {
			return "[]"
		}
		// Check if array contains objects with blank? For <root><a/><b>hi</b></root> compact gives {"a": {},"b": "hi"}? Actually earlier compact for that gave {"root": {"a": {},"b": "hi"}} with {} inline (not expanded). Good. Our compact for empty objects inside should be inline {} (not expanded). Good. So for compact, empty objects/arrays are inline.
		parts := make([]string, len(x))
		for i, e := range x {
