package cmd

import (
	"bytes"
	"encoding/xml"
	"strings"
)

type xpNode struct {
	name     string
	attrs    map[string]string
	children []*xpNode
	texts    []string
	parent   *xpNode
	isDoc    bool
}

func parseForXpath(data []byte) (*xpNode, string) {
	dec := xml.NewDecoder(bytes.NewReader(data))
	dec.Strict = true
	dec.AutoClose = xml.HTMLAutoClose
	dec.Entity = xml.HTMLEntity
	doc := &xpNode{isDoc: true}
	var stack []*xpNode
	stack = append(stack, doc)
	for {
		tok, err := dec.Token()
		if err != nil {
			if err.Error() == "EOF" {
				break
			}
			msg := err.Error()
			if strings.Contains(msg, "invalid XML") {
				return nil, "Error: xmlquery: invalid XML document\n"
			}
			return nil, "Error: " + msg + "\n"
		}
		switch t := tok.(type) {
		case xml.StartElement:
			name := t.Name.Local
			attrs := map[string]string{}
			for _, a := range t.Attr {
				attrs[a.Name.Local] = a.Value
			}
			n := &xpNode{name: name, attrs: attrs, parent: stack[len(stack)-1]}
			stack[len(stack)-1].children = append(stack[len(stack)-1].children, n)
			stack = append(stack, n)
		case xml.EndElement:
			if len(stack) <= 1 {
				return nil, "Error: xmlquery: invalid XML document\n"
			}
			stack = stack[:len(stack)-1]
		case xml.CharData:
			s := string(t)
			if strings.TrimSpace(s) == "" {
				continue
			}
			top := stack[len(stack)-1]
			top.texts = append(top.texts, s)
		case xml.Comment, xml.Directive, xml.ProcInst:
			continue
		}
	}
	return doc, ""
}
GOEOF
