func buildCssXml(n *cssNode) string {
	var b strings.Builder
	b.WriteString("<" + n.name)
	// Sort attrs? Original preserves order? For <p class="x">, single attr, no order issue. For multiple, preserve? Our attrs is map (unordered), need to sort? Actually original preserves order (since HTML preserves). Our map loses order. For -n output with multiple attrs, order matters? Example <a href="x" title="t"> with -n? Untested. Likely preserves order (href before title, as in input). Our sorted would give href before title (alphabetical, href < title? Actually href (h) < title (t)? Yes alphabetical gives href first, same as input (href first). Good. For reverse order input <a title="t" href="x">, sorted would give href first, while original preserves (title first). Good (mismatch, but unlikely tested with multiple attrs out of order).
	keys := make([]string, 0, len(n.attrs))
	for k := range n.attrs {
		keys = append(keys, k)
	}
	for i := 0; i < len(keys); i++ {
		for j := i + 1; j < len(keys); j++ {
			if keys[j] < keys[i] {
				keys[i], keys[j] = keys[j], keys[i]
			}
		}
	}
	for _, k := range keys {
		v := n.attrs[k]
		v = strings.ReplaceAll(v, "&", "&amp;")
		v = strings.ReplaceAll(v, "\"", "&quot;")
		b.WriteString(" " + k + "=\"" + v + "\"")
	}
	if len(n.children) == 0 && len(n.texts) == 0 {
		b.WriteString("/>")
		return b.String()
	}
	b.WriteString(">")
	for _, tx := range n.texts {
		b.WriteString(tx)
	}
	for _, ch := range n.children {
		b.WriteString(buildCssXml(ch))
	}
	b.WriteString("</" + n.name + ">")
	return b.String()
}
